// CUDA kernel for matrix multiplication using shared memory and coalesced access
__global__ void matmul_kernel_coalesced(const float* A, const float* B, float* C, int N) {
    // Declare shared memory for A_sub and B_sub
    // BLOCK_SIZE is 16
    __shared__ float A_shared[16][16];
    __shared__ float B_shared[16][16]; // B is transposed in shared memory

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Iterate over tiles
    for (int tile = 0; tile < (N + 16 - 1) / 16; ++tile) {
        // Load A_sub from global memory to shared memory (coalesced)
        if (row < N && (tile * 16 + threadIdx.x) < N) {
            A_shared[threadIdx.y][threadIdx.x] = A[row * N + (tile * 16 + threadIdx.x)];
        } else {
            A_shared[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        // Load B_sub from global memory to shared memory (coalesced, transposed)
        // Each thread loads one element of B_sub. To achieve coalesced access for B,
        // we load B[k][col] into B_shared[threadIdx.x][threadIdx.y].
        // This effectively transposes B in shared memory.
        if (col < N && (tile * 16 + threadIdx.y) < N) {
            B_shared[threadIdx.x][threadIdx.y] = B[(tile * 16 + threadIdx.y) * N + col];
        } else {
            B_shared[threadIdx.x][threadIdx.y] = 0.0f; // Pad with zeros if out of bounds
        }
        __syncthreads();

        // Perform dot product on shared memory tiles
        if (row < N && col < N) {
            for (int k = 0; k < 16; ++k) {
                // Access A_shared normally, B_shared with transposed indices
                sum += A_shared[threadIdx.y][k] * B_shared[threadIdx.x][k];
            }
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
