    dim3 block_dim(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid_dim((N + block_dim.x - 1) / block_dim.x, (N + block_dim.y - 1) / block_dim.y);

    // Launch the kernel
    matmul_kernel_coalesced<<<grid_dim, block_dim>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N
